/* ============================================================
   ROOT — ported from layouts/Root.tsx, using state instead of
   react-router (not available in this sandbox)
============================================================ */
export default function App() {
  const [page, setPage] = useState("home");
  const navigate = (to) => { setPage(to); window.scrollTo(0, 0); };
  const hideFooter = page === "auth";

  const pageTitles = {
    "teen-dashboard": "For Teens",
    "parent-dashboard": "For Parents",
    "ai-detection": "AI Shield",
    "learning-hub": "Learning Hub",
    about: "About",
    contact: "Contact",
  };

  return (
    <div className="yg-root min-h-screen" style={{ background: "#F9F7F2" }}>
      <GlobalStyles />
      <Navbar page={page} navigate={navigate} />
      <main>
        {page === "home" && <LandingPage navigate={navigate} />}
        {page === "auth" && <AuthPage navigate={navigate} />}
        {pageTitles[page] && <PlaceholderPage title={pageTitles[page]} navigate={navigate} />}
      </main>
      {!hideFooter && <Footer navigate={navigate} />}
    </div>
  );
}
